    // внешние стороны = забор
    let perf='';
    const edge=(x1,y1,x2,y2)=>{ perf+=`<line class="${opt.fence?'pfFence':''}" x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${I.wood}" stroke-width="3.4" stroke-linecap="round"/>`; };
