      inner+=`<g class="k8pop" style="animation-delay:.15s">${ray(166,132,0,80,I.grn,{w:3})}${ray(166,132,-90,90,I.grn,{w:3})}${rightMark(166,132,-90,16,I.grn)}${pt(166,132)}
      ${tx(166,158,13,I.ink,'прямой = 90°',{b:1})}</g>`;
