      if(step>=0&&step<=14){ st.go=0; st.pick=null; }
      if(step===6||step===8) st.go=0;
      if(step===10||step===11) st.pick=null;
      if(step===13){ st.mq=0; st.msel=null; }
      if(step===14){ st.sel=null; st.q=0; }
